def transform(grid):
    h, w = len(grid), len(grid[0])
    bg = max(set(v for row in grid for v in row),
             key=lambda v: sum(row.count(v) for row in grid))
    seen = set()
    comps = []

    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == bg or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            cells = set()
            while stack:
                y, x = stack.pop()
                cells.add((y, x))
                for ny, nx in ((y-1, x), (y+1, x), (y, x-1), (y, x+1)):
                    if (0 <= ny < h and 0 <= nx < w and
                            grid[ny][nx] == color and (ny, nx) not in seen):
                        seen.add((ny, nx))
                        stack.append((ny, nx))
            comps.append((color, cells))

    # Find the distinctive straight, perpendicular L-shaped component.
    key = None
    for color, cells in comps:
        for r, c in cells:
            rows = {y for y, x in cells if x == c}
            cols = {x for y, x in cells if y == r}
            if len(rows) < 3 or len(cols) < 3:
                continue
            if any(y < r for y in rows) and any(y > r for y in rows):
                continue
            if any(x < c for x in cols) and any(x > c for x in cols):
                continue
            expected = {(y, c) for y in range(min(rows), max(rows) + 1)}
            expected |= {(r, x) for x in range(min(cols), max(cols) + 1)}
            if cells == expected:
                candidate = (len(cells), color, cells, r, c)
                if key is None or candidate[0] > key[0]:
                    key = candidate

    if key is None:
        return [row[:] for row in grid]

    _, key_color, key_cells, kr, kc = key
    mid_r, mid_c = (h - 1) / 2, (w - 1) / 2
    key_bottom = kr > mid_r
    key_right = kc > mid_c

    # Recolor the largest object in the diagonally opposite grid quadrant.
    target = None
    for color, cells in comps:
        if cells == key_cells:
            continue
        avg_r = sum(y for y, x in cells) / len(cells)
        avg_c = sum(x for y, x in cells) / len(cells)
        opposite_row = avg_r < mid_r if key_bottom else avg_r > mid_r
        opposite_col = avg_c < mid_c if key_right else avg_c > mid_c
        if opposite_row and opposite_col:
            if target is None or len(cells) > len(target):
                target = cells

    out = [row[:] for row in grid]
    if target:
        for r, c in target:
            out[r][c] = key_color
    return out
